import XCTest
@testable import OpenPatchCore

/// Application layer key agreement (docs/04-protocol.md). The vectors in docs/vectors/session-key-agreement.json are
/// generated by the Rust pod implementation and re-derived by an independent Python script; every test that reads
/// them proves that this Swift implementation is byte-identical.
final class SessionHandshakeTests: XCTestCase {
    // MARK: vector file

    private static let vectors: [String: Any] = {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<6 { url.deleteLastPathComponent() }   // .../Tests/OpenPatchCoreTests/File.swift -> repository root
        let file = url.appendingPathComponent("docs/vectors/session-key-agreement.json")
        let data = try! Data(contentsOf: file)
        return try! JSONSerialization.jsonObject(with: data) as! [String: Any]
    }()

    private func dict(_ v: Any?) -> [String: Any] { v as! [String: Any] }
    private func hex(_ v: Any?) -> [UInt8] {
        let s = v as! String
        var out: [UInt8] = []
        var index = s.startIndex
        while index < s.endIndex {
            let next = s.index(index, offsetBy: 2)
            out.append(UInt8(s[index..<next], radix: 16)!)
            index = next
        }
        return out
    }
    private func data(_ v: Any?) -> Data { Data(hex(v)) }
    private func str(_ bytes: [UInt8]) -> String { bytes.map { String(format: "%02x", $0) }.joined() }

    private var pairingCases: [[String: Any]] { Self.vectors["pairing"] as! [[String: Any]] }
    private var sessionCase: [String: Any] { dict(Self.vectors["session"]) }

    /// "Random" source that replays the vector's secret and nonce (secret first, then nonce).
    private func fixedRandom(_ c: [String: Any]) -> (Int) -> [UInt8] {
        var queue = [hex(c["app_eph_secret"]), hex(c["app_nonce"])]
        return { count in
            let next = queue.removeFirst()
            XCTAssertEqual(next.count, count)
            return next
        }
    }

    // MARK: primitives against published known answers

    func test_aes128_matchesFIPS197AppendixC1() {
        let key = (0..<16).map { UInt8($0) }
        let plain = (0..<16).map { UInt8($0 * 0x11) }
        XCTAssertEqual(str(SessionCrypto.AES128(key: key).encrypt(block: plain)), "69c4e0d86a7b0430d8cdb78070b4c55a")
    }

    func test_aesCCM_matchesRFC3610PacketVector1() {
        let c = dict(dict(Self.vectors["primitives"])["aes128_ccm_rfc3610_packet_vector_1"])
        let ccm = SessionCrypto.AESCCM(key: hex(c["key"]))
        let sealed = ccm.seal(nonce: hex(c["nonce"]), aad: hex(c["aad"]), plaintext: hex(c["plaintext"]))
        XCTAssertEqual(sealed, hex(c["ciphertext"]) + hex(c["tag"]))
        XCTAssertEqual(ccm.open(nonce: hex(c["nonce"]), aad: hex(c["aad"]), sealed: sealed), hex(c["plaintext"]))
    }

    func test_aesCCM_rejectsAnyModification() {
        let ccm = SessionCrypto.AESCCM(key: [UInt8](repeating: 7, count: 16))
        let nonce = [UInt8](repeating: 1, count: 13)
        let sealed = ccm.seal(nonce: nonce, aad: [1, 2, 3], plaintext: Array(0..<40))
        XCTAssertNotNil(ccm.open(nonce: nonce, aad: [1, 2, 3], sealed: sealed))
        for i in 0..<sealed.count {
            var bad = sealed; bad[i] ^= 0x01
            XCTAssertNil(ccm.open(nonce: nonce, aad: [1, 2, 3], sealed: bad), "byte \(i)")
        }
        XCTAssertNil(ccm.open(nonce: nonce, aad: [1, 2, 4], sealed: sealed))
        var other = nonce; other[12] ^= 1
        XCTAssertNil(ccm.open(nonce: other, aad: [1, 2, 3], sealed: sealed))
        XCTAssertNil(ccm.open(nonce: nonce, aad: [1, 2, 3], sealed: Array(sealed.prefix(5))))
    }

    func test_x25519_matchesRFC7748() {
        let p = dict(dict(Self.vectors["primitives"])["x25519_rfc7748_6_1"])
        XCTAssertEqual(try SessionCrypto.x25519KeyPair(secret: hex(p["alice_secret"])).publicKey, hex(p["alice_public"]))
        XCTAssertEqual(SessionCrypto.x25519(secret: hex(p["alice_secret"]), peer: hex(p["bob_public"])), hex(p["shared"]))
        XCTAssertEqual(SessionCrypto.x25519(secret: hex(p["bob_secret"]), peer: hex(p["alice_public"])), hex(p["shared"]))
    }

    func test_x25519_lowOrderPointsAreRejected() {
        for point in Self.vectors["low_order_public_keys"] as! [String] {
            XCTAssertNil(SessionCrypto.x25519(secret: [UInt8](repeating: 9, count: 32), peer: hex(point)), point)
        }
    }

    func test_hkdf_matchesRFC5869() {
        let h = dict(dict(Self.vectors["primitives"])["hkdf_sha256_rfc5869_a1"])
        XCTAssertEqual(SessionCrypto.hkdf(salt: hex(h["salt"]), ikm: hex(h["ikm"]), info: hex(h["info"]), length: h["length"] as! Int), hex(h["okm"]))
    }

    // MARK: handshake vectors

    func test_pairingVectors_areReproducedByteForByte() throws {
        XCTAssertEqual(pairingCases.count, 2)
        for c in pairingCases {
            let name = c["name"] as! String
            let frames = dict(c["frames"])
            let initiator = try SessionHandshake.Initiator(pairingWithOOB: hex(c["oob"]), random: fixedRandom(c))
            XCTAssertEqual(initiator.initFrame(), data(frames["init_request"]), name)
            let finish = try initiator.finishFrame(initResponse: data(frames["init_response"]))
            XCTAssertEqual(finish, data(frames["finish_request"]), name)
            XCTAssertEqual(try initiator.complete(finishResponse: data(frames["finish_response"])), .paired(secret: hex(c["ps"])), name)
        }
    }

    func test_pairingVectors_intermediateValues() throws {
        for c in pairingCases {
            let pubA = hex(c["app_eph_public"]), pubB = hex(c["pod_eph_public"])
            XCTAssertEqual(try SessionCrypto.x25519KeyPair(secret: hex(c["app_eph_secret"])).publicKey, pubA)
            let dh = try XCTUnwrap(SessionCrypto.x25519(secret: hex(c["app_eph_secret"]), peer: pubB))
            XCTAssertEqual(dh, hex(c["dh"]))
            XCTAssertEqual(dh, SessionCrypto.x25519(secret: hex(c["pod_eph_secret"]), peer: pubA))
            let th = SessionHandshake.transcriptHash(mode: .pair, psID: [0, 0, 0, 0], pubA: pubA, pubB: pubB, nonceA: hex(c["app_nonce"]), nonceB: hex(c["pod_nonce"]))
            XCTAssertEqual(th, hex(c["transcript_hash"]))
            XCTAssertEqual(SessionHandshake.oobSalt(hex(c["oob"])), hex(c["oob_salt"]))
            let d = SessionHandshake.derivePairing(dh: dh, oobSalt: hex(c["oob_salt"]), transcriptHash: th)
            XCTAssertEqual(d.secret, hex(c["ps"]))
            XCTAssertEqual(d.confirmKey, hex(c["confirm_key"]))
            XCTAssertEqual(SessionHandshake.confirmTag(confirmKey: d.confirmKey, side: .pod, transcriptHash: th), hex(c["confirm_pod"]))
            XCTAssertEqual(SessionHandshake.confirmTag(confirmKey: d.confirmKey, side: .app, transcriptHash: th), hex(c["confirm_app"]))
        }
    }

    func test_sessionVector_isReproducedByteForByte() throws {
        let c = sessionCase
        let frames = dict(c["frames"])
        let ps = hex(c["ps"])
        XCTAssertEqual(ps, hex(pairingCases[0]["ps"]), "the session case uses the secret of the first pairing case")
        XCTAssertEqual(SessionHandshake.psID(ps), hex(c["ps_id"]))
        let initiator = try SessionHandshake.Initiator(sessionWith: ps, random: fixedRandom(c))
        XCTAssertEqual(initiator.initFrame(), data(frames["init_request"]))
        XCTAssertEqual(try initiator.finishFrame(initResponse: data(frames["init_response"])), data(frames["finish_request"]))
        let outcome = try initiator.complete(finishResponse: data(frames["finish_response"]))
        let keys = SessionHandshake.SessionKeys(keyC2P: hex(c["key_c2p"]), keyP2C: hex(c["key_p2c"]), salt: hex(c["salt"]))
        XCTAssertEqual(outcome, .session(keys))
    }

    func test_sessionVector_intermediateValues() throws {
        let c = sessionCase
        let ps = hex(c["ps"])
        let dh = try XCTUnwrap(SessionCrypto.x25519(secret: hex(c["app_eph_secret"]), peer: hex(c["pod_eph_public"])))
        XCTAssertEqual(dh, hex(c["dh"]))
        let th = SessionHandshake.transcriptHash(mode: .session, psID: hex(c["ps_id"]), pubA: hex(c["app_eph_public"]), pubB: hex(c["pod_eph_public"]),
                                                 nonceA: hex(c["app_nonce"]), nonceB: hex(c["pod_nonce"]))
        XCTAssertEqual(th, hex(c["transcript_hash"]))
        let d = SessionHandshake.deriveSession(dh: dh, pairingSecret: ps, transcriptHash: th)
        XCTAssertEqual(d.keys.keyC2P, hex(c["key_c2p"]))
        XCTAssertEqual(d.keys.keyP2C, hex(c["key_p2c"]))
        XCTAssertEqual(d.keys.salt, hex(c["salt"]))
        XCTAssertEqual(d.confirmKey, hex(c["confirm_key"]))
        XCTAssertEqual(SessionHandshake.confirmTag(confirmKey: d.confirmKey, side: .pod, transcriptHash: th), hex(c["confirm_pod"]))
        XCTAssertEqual(SessionHandshake.confirmTag(confirmKey: d.confirmKey, side: .app, transcriptHash: th), hex(c["confirm_app"]))
    }

    // MARK: encrypted traffic vectors

    private func sessionChannel() -> SecureChannel {
        let c = sessionCase
        return SecureChannel(keys: SessionHandshake.SessionKeys(keyC2P: hex(c["key_c2p"]), keyP2C: hex(c["key_p2c"]), salt: hex(c["salt"])))
    }

    func test_trafficVectors_commandsAreSealedByteForByte_responsesAndNotificationsOpen() throws {
        let channel = sessionChannel()
        let traffic = Self.vectors["traffic"] as! [[String: Any]]
        XCTAssertEqual(traffic.map { $0["dir"] as! Int }, [0, 0, 1, 2])
        for t in traffic {
            let name = t["name"] as! String
            let type = UInt8(t["type"] as! Int), seq = UInt16(t["seq"] as! Int)
            let payload = try V1.parseTLVs(hex(t["payload"]))
            if (t["dir"] as! Int) == 0 {
                XCTAssertEqual(channel.seal(V1.Message(type: type, seq: seq, tlvs: payload)), data(t["frame"]), name)
            } else {
                let message = try channel.open(data(t["frame"]))
                XCTAssertEqual(message.type, type, name)
                XCTAssertEqual(message.seq, seq, name)
                XCTAssertEqual(message.tlvs, payload, name)
                XCTAssertTrue(message.isResponse, name)
            }
        }
    }

    func test_channel_refusesTamperedReflectedAndPlaintextFrames() throws {
        let channel = sessionChannel()
        let traffic = Self.vectors["traffic"] as! [[String: Any]]
        let response = [UInt8](data(traffic[2]["frame"]))
        // flipped ciphertext bit with a fixed-up CRC: authentication fails
        var bad = response
        bad[V1.headerSize] ^= 1
        let crc = V1.crc16(bad[0..<(bad.count - 2)])
        bad[bad.count - 2] = UInt8(crc & 0xFF); bad[bad.count - 1] = UInt8(crc >> 8)
        XCTAssertThrowsError(try channel.open(Data(bad))) { XCTAssertEqual($0 as? SecureChannel.Failure, .authentication) }
        // our own command is not a valid inbound frame (no reflection)
        XCTAssertThrowsError(try channel.open(data(traffic[1]["frame"]))) { XCTAssertEqual($0 as? SecureChannel.Failure, .malformed) }
        // a plaintext frame is refused
        let plain = V1.encode(V1.Message(type: 0x85, flags: V1.flagResponse, seq: 2, tlvs: [V1.TLV(.result, u8: 0)]))
        XCTAssertThrowsError(try channel.open(plain)) { XCTAssertEqual($0 as? SecureChannel.Failure, .notEncrypted) }
        // the notification is not a response of the same seq (nonce direction 2 vs 1): relabelled type fails
        var relabel = [UInt8](data(traffic[3]["frame"]))
        relabel[1] = 0x85
        let c2 = V1.crc16(relabel[0..<(relabel.count - 2)])
        relabel[relabel.count - 2] = UInt8(c2 & 0xFF); relabel[relabel.count - 1] = UInt8(c2 >> 8)
        XCTAssertThrowsError(try channel.open(Data(relabel))) { XCTAssertEqual($0 as? SecureChannel.Failure, .authentication) }
    }

    func test_channel_ofAnotherSessionCannotOpenTheFrames() throws {
        let other = SecureChannel(keys: SessionHandshake.SessionKeys(keyC2P: [UInt8](repeating: 1, count: 16), keyP2C: [UInt8](repeating: 2, count: 16), salt: [0, 0, 0, 0]))
        let traffic = Self.vectors["traffic"] as! [[String: Any]]
        XCTAssertThrowsError(try other.open(data(traffic[2]["frame"]))) { XCTAssertEqual($0 as? SecureChannel.Failure, .authentication) }
    }

    // MARK: failure handling

    private func rewriteResponse(_ frame: Data, mutate: (inout V1.Message) -> Void) throws -> Data {
        var m = try V1.decode(frame)
        mutate(&m)
        return V1.encode(m)
    }

    func test_initiator_rejectsAlteredPodKeyConfirmationOrWrongSecret() throws {
        let c = sessionCase
        let frames = dict(c["frames"])
        let ps = hex(c["ps"])
        // pod key altered (the confirmation no longer verifies)
        let altered = try rewriteResponse(data(frames["init_response"])) { m in
            let i = m.tlvs.firstIndex { $0.tag == SessionHandshake.Tag.ephPub }!
            m.tlvs[i].value[0] ^= 0x40
        }
        let a = try SessionHandshake.Initiator(sessionWith: ps, random: fixedRandom(c))
        XCTAssertThrowsError(try a.finishFrame(initResponse: altered)) { XCTAssertEqual($0 as? SessionHandshake.Failure, .badConfirmation) }
        // wrong pairing secret on the phone: the pod's confirmation (made with the right one) cannot verify
        var wrong = ps; wrong[0] ^= 1
        let b = try SessionHandshake.Initiator(sessionWith: wrong, random: fixedRandom(c))
        XCTAssertThrowsError(try b.finishFrame(initResponse: data(frames["init_response"]))) { XCTAssertEqual($0 as? SessionHandshake.Failure, .badConfirmation) }
        // wrong OOB code
        let p = pairingCases[0]
        let d = try SessionHandshake.Initiator(pairingWithOOB: Array("999999".utf8), random: fixedRandom(p))
        XCTAssertThrowsError(try d.finishFrame(initResponse: data(dict(p["frames"])["init_response"]))) { XCTAssertEqual($0 as? SessionHandshake.Failure, .badConfirmation) }
    }

    func test_initiator_rejectsLowOrderPodKey_andReportsPodRejections() throws {
        let c = sessionCase
        let frames = dict(c["frames"])
        for point in Self.vectors["low_order_public_keys"] as! [String] {
            let evil = try rewriteResponse(data(frames["init_response"])) { m in
                let i = m.tlvs.firstIndex { $0.tag == SessionHandshake.Tag.ephPub }!
                m.tlvs[i].value = hex(point)
            }
            let initiator = try SessionHandshake.Initiator(sessionWith: hex(c["ps"]), random: fixedRandom(c))
            XCTAssertThrowsError(try initiator.finishFrame(initResponse: evil)) { XCTAssertEqual($0 as? SessionHandshake.Failure, .lowOrderPoint) }
        }
        let reject = V1.encode(V1.Message(type: SessionHandshake.FrameType.sessionInit | V1.responseFlag, flags: V1.flagResponse, seq: 0,
                                          tlvs: [V1.TLV(.result, u8: V1.Result.pair.rawValue)]))
        let initiator = try SessionHandshake.Initiator(sessionWith: hex(c["ps"]), random: fixedRandom(c))
        XCTAssertThrowsError(try initiator.finishFrame(initResponse: reject)) { XCTAssertEqual($0 as? SessionHandshake.Failure, .rejected(22)) }
        // after a rejected INIT no outcome exists, even if a FINISH response with OK arrives
        XCTAssertThrowsError(try initiator.complete(finishResponse: data(dict(c["frames"])["finish_response"])))
    }

    func test_initiator_finishWithoutVerifiedInitResponseYieldsNothing() throws {
        let c = sessionCase
        let initiator = try SessionHandshake.Initiator(sessionWith: hex(c["ps"]), random: fixedRandom(c))
        XCTAssertThrowsError(try initiator.complete(finishResponse: data(dict(c["frames"])["finish_response"]))) {
            XCTAssertEqual($0 as? SessionHandshake.Failure, .malformed)
        }
    }
}
